bool Player::castSpell(const std::string& spellName) {
    const auto& spell = g_spells().getSpellByName(spellName);
    if (!spell || !spell->isInstant()) {
        return false;
    }

    const auto& instantSpell = std::static_pointer_cast<InstantSpell>(spell);
    if (!instantSpell) {
        return false;
    }

    const auto& player = static_self_cast<Player>();
    if (!instantSpell->canCast(player)) {
        return false;
    }

	std::string emptyParam;
    return instantSpell->playerCastInstant(static_self_cast<Player>(), emptyParam);
}
